class Solution {
public:
    int minPathCost(std::vector<std::vector<int>>& grid, std::vector<std::vector<int>>& moveCost) {
        int m = grid.size(), n = grid[0].size();
        std::vector<int> dp = grid[0];
        for (int r = 0; r < m - 1; ++r) {
            std::vector<int> next_dp(n, 1e9);
            for (int c1 = 0; c1 < n; ++c1) {
                int val = grid[r][c1];
                for (int c2 = 0; c2 < n; ++c2) {
                    int cand = dp[c1] + moveCost[val][c2] + grid[r + 1][c2];
                    next_dp[c2] = std::min(next_dp[c2], cand);
                }
            }
            dp = std::move(next_dp);
        }
        int ans = 1e9;
        for (int x : dp) ans = std::min(ans, x);
        return ans;
    }
};

class Solution {
    public int minPathCost(int[][] grid, int[][] moveCost) {
        int m = grid.length, n = grid[0].length;
        int[] dp = grid[0].clone();
        for (int r = 0; r < m - 1; r++) {
            int[] nextDp = new int[n];
            java.util.Arrays.fill(nextDp, (int) 1e9);
            for (int c1 = 0; c1 < n; c1++) {
                int val = grid[r][c1];
                for (int c2 = 0; c2 < n; c2++) {
                    int cand = dp[c1] + moveCost[val][c2] + grid[r + 1][c2];
                    nextDp[c2] = Math.min(nextDp[c2], cand);
                }
            }
            dp = nextDp;
        }
        int ans = (int) 1e9;
        for (int x : dp) ans = Math.min(ans, x);
        return ans;
    }
}

var minPathCost = function(grid, moveCost) {
    const m = grid.length, n = grid[0].length;
    let dp = Array.from(grid[0]);
    for (let r = 0; r < m - 1; r++) {
        const nextDp = new Int32Array(n).fill(1e9);
        for (let c1 = 0; c1 < n; c1++) {
            const val = grid[r][c1];
            for (let c2 = 0; c2 < n; c2++) {
                const cand = dp[c1] + moveCost[val][c2] + grid[r + 1][c2];
                if (cand < nextDp[c2]) nextDp[c2] = cand;
            }
        }
        dp = nextDp;
    }
    let ans = 1e9;
    for (let i = 0; i < n; i++) if (dp[i] < ans) ans = dp[i];
    return ans;
};
